    // (Pair.with(2.0f, 2.0f))
    public static Pair<Float, Float> findClosestElements(ArrayList<Float> numbers) {

completion:
if (numbers.size() < 2) {
            throw new IllegalArgumentException("Array list must have at least two elements");
        }

        float minDiff = Float.MAX_VALUE;
        float minNum = numbers.get(0);
        float maxNum = numbers.get(0);

        for (int i = 1; i < numbers.size(); i++) {
